import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';

export class BookStore {
  constructor(filePath) {
    this.filePath = filePath;
    this.pending = Promise.resolve();
  }

  async all() {
    try {
      const books = JSON.parse(await readFile(this.filePath, 'utf8'));
      if (!Array.isArray(books)) throw new Error('Books file must contain an array');
      return books;
    } catch (error) {
      if (error.code === 'ENOENT') return [];
      throw error;
    }
  }

  async change(update) {
    const operation = this.pending.then(async () => {
      const books = await this.all();
      const result = update(books);
      if (result === null) return null;

      await mkdir(path.dirname(this.filePath), { recursive: true });
      const temporary = `${this.filePath}.${randomUUID()}.tmp`;
      try {
        await writeFile(temporary, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
        await rename(temporary, this.filePath);
      } catch (error) {
        // A failed write should not leave a partial books file behind.
        const { rm } = await import('node:fs/promises');
        await rm(temporary, { force: true }).catch(() => {});
        throw error;
      }
      return result;
    });
    // Keep the queue usable even if an individual operation fails.
    this.pending = operation.then(() => undefined, () => undefined);
    return operation;
  }

  add({ title, author, notes }) {
    return this.change((books) => {
      const book = {
        id: randomUUID(),
        title,
        author,
        notes,
        status: 'reading',
        createdAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.unshift(book);
      return book;
    });
  }

  finish(id) {
    return this.change((books) => {
      const book = books.find((item) => item.id === id);
      if (!book) return null;
      if (book.status !== 'finished') {
        book.status = 'finished';
        book.finishedAt = new Date().toISOString();
      }
      return book;
    });
  }
}

