const arrow = '<svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M4 10h11m-4.5-4.5L15 10l-4.5 4.5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const bookIcon = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 6.5c-2.4-1.8-5.4-2-8.5-1.5v12.5c3.1-.5 6.1-.3 8.5 1.5m0-12.5c2.4-1.8 5.4-2 8.5-1.5v12.5c-3.1-.5-6.1-.3-8.5 1.5m0-12.5V19" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';

export function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function layout(content, { title = 'The Reading Room', page = 'home' } = {}) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#f7f5ef">
  <meta name="description" content="A quiet little home for the books you're reading and the ones you've finished.">
  <title>${escapeHtml(title)} · The Reading Room</title>
  <link rel="icon" href="/favicon.svg" type="image/svg+xml">
  <link rel="stylesheet" href="/styles.css">
  <script src="/app.js" defer></script>
</head>
<body class="page-${page}">
  <div class="site-shell">
    <header class="site-header">
      <a class="brand" href="/" aria-label="The Reading Room home"><span class="brand-mark">${bookIcon}</span><span>the reading room<span class="brand-dot">.</span></span></a>
      <span class="header-caption"><span class="header-caption__line"></span> A place for every page</span>
    </header>
    ${content}
    <footer class="site-footer"><span>THE READING ROOM</span><span>Keep the stories close.</span><span>Made for the love of reading</span></footer>
  </div>
</body>
</html>`;
}

function palette(id) {
  const colors = ['sage', 'clay', 'ink', 'lavender', 'ochre'];
  const hash = [...id].reduce((value, char) => value + char.charCodeAt(0), 0);
  return colors[hash % colors.length];
}

function cover(book, large = false) {
  return `<div class="book-cover cover-${palette(book.id)}${large ? ' book-cover--large' : ''}" aria-hidden="true">
    <span class="book-cover__ornament">✳</span>
    <span class="book-cover__type"><span class="book-cover__title">${escapeHtml(book.title)}</span><span class="book-cover__author">${escapeHtml(book.author)}</span></span>
    <span class="book-cover__rule"></span>
  </div>`;
}

function bookCard(book) {
  const finished = book.status === 'finished';
  return `<article class="book-card">
    <a class="book-card__cover-link" href="/books/${book.id}" aria-label="View ${escapeHtml(book.title)}">${cover(book)}</a>
    <div class="book-card__body">
      <div class="book-card__top"><span class="status-tag ${finished ? 'status-tag--finished' : ''}"><span class="status-tag__dot"></span>${finished ? 'Finished' : 'Currently reading'}</span></div>
      <div class="book-card__info"><h3><a href="/books/${book.id}">${escapeHtml(book.title)}</a></h3><p class="book-author">by ${escapeHtml(book.author)}</p>${book.notes ? `<p class="book-card__excerpt">${escapeHtml(book.notes)}</p>` : ''}</div>
      <div class="book-card__bottom"><a class="text-link" href="/books/${book.id}">View book ${arrow}</a>${finished ? '' : `<form action="/books/${book.id}/finish" method="post"><button class="finish-link" type="submit">Mark as finished <span aria-hidden="true">✓</span></button></form>`}</div>
    </div>
  </article>`;
}

function emptyState(finished) {
  return `<div class="empty-state"><div class="empty-state__art" aria-hidden="true"><span></span><span></span><span></span></div><div><h3>${finished ? 'A fresh start.' : 'Your next chapter starts here.'}</h3><p>${finished ? 'Books you finish will find a home on this shelf.' : 'Add a book using the form, and it’ll be right here waiting for you.'}</p></div></div>`;
}

function shelf(books, { finished = false } = {}) {
  return `<section class="shelf" aria-labelledby="${finished ? 'finished-heading' : 'reading-heading'}">
    <div class="section-heading"><div><span class="eyebrow"><span class="eyebrow-line"></span>${finished ? 'THE ARCHIVE' : 'ON THE NIGHTSTAND'}</span><h2 id="${finished ? 'finished-heading' : 'reading-heading'}">${finished ? 'Finished books' : 'Currently reading'} <span class="section-count">${books.length.toString().padStart(2, '0')}</span></h2><p>${finished ? 'The ones that stayed with you.' : 'The stories keeping you company.'}</p></div></div>
    <div class="book-list">${books.length ? books.map(bookCard).join('') : emptyState(finished)}</div>
  </section>`;
}

function addForm(form = {}, error = '') {
  return `<aside class="add-panel" id="add-book" aria-labelledby="add-heading">
    <div class="add-panel__top"><span class="add-panel__icon">${bookIcon}</span><span class="add-panel__label">A NEW STORY</span></div>
    <h2 id="add-heading">Add to your<br><em>reading list.</em></h2>
    <p class="add-panel__intro">Every great book deserves a place to call home.</p>
    ${error ? `<p class="form-error" role="alert">${escapeHtml(error)}</p>` : ''}
    <form action="/books" method="post" class="add-form">
      <div class="field"><label for="title">Book title <span aria-hidden="true">*</span></label><input id="title" name="title" type="text" placeholder="e.g. The Midnight Library" maxlength="160" value="${escapeHtml(form.title)}" required></div>
      <div class="field"><label for="author">Author <span aria-hidden="true">*</span></label><input id="author" name="author" type="text" placeholder="e.g. Matt Haig" maxlength="160" value="${escapeHtml(form.author)}" required></div>
      <div class="field"><label for="notes">Your notes <span class="field-optional">OPTIONAL</span></label><textarea id="notes" name="notes" rows="4" maxlength="4000" placeholder="A thought, a feeling, a favorite line…">${escapeHtml(form.notes)}</textarea></div>
      <button type="submit" class="primary-button">Add to my books <span>${arrow}</span></button>
    </form>
    <p class="add-panel__footnote">No accounts, no fuss. Just your books.</p>
  </aside>`;
}

export function renderHome(books, options = {}) {
  const reading = books.filter((book) => book.status !== 'finished');
  const finished = books.filter((book) => book.status === 'finished').sort((a, b) => (b.finishedAt || '').localeCompare(a.finishedAt || ''));
  return layout(`<main>
    <section class="hero"><div class="hero__copy"><span class="eyebrow"><span class="eyebrow-line"></span>YOUR PERSONAL BOOKSHELF</span><h1>Good stories deserve<br>a place to <em>stay.</em></h1><p>A simple little space for what you’re reading, what you’ve loved, and everything in between.</p></div><div class="hero__summary"><span class="summary-label">YOUR SHELF AT A GLANCE</span><div class="summary-stats"><div><strong>${reading.length}</strong><span>Reading now</span></div><span class="summary-divider"></span><div><strong>${finished.length}</strong><span>Finished</span></div></div><span class="summary-bottom">ONE PAGE AT A TIME <span aria-hidden="true">↗</span></span></div></section>
    <div class="dashboard"><div class="dashboard__shelves">${shelf(reading)}${shelf(finished, { finished: true })}</div>${addForm(options.form, options.error)}</div>
  </main>`, { page: 'home' });
}

function formatDate(value) {
  if (!value) return '';
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? '' : new Intl.DateTimeFormat('en', { month: 'long', day: 'numeric', year: 'numeric', timeZone: 'UTC' }).format(date);
}

export function renderDetail(book) {
  const finished = book.status === 'finished';
  return layout(`<main class="detail-main"><div class="detail-back"><a href="/" class="back-link"><span aria-hidden="true">←</span> Back to your shelf</a><span class="detail-back__trail">YOUR BOOKS <span>/</span> ${escapeHtml(book.title)}</span></div>
    <article class="detail-card"><div class="detail-card__visual"><div class="detail-card__cover-wrap">${cover(book, true)}</div><span class="detail-card__visual-caption">A STORY WORTH KEEPING <span aria-hidden="true">✳</span></span></div>
    <div class="detail-card__content"><span class="eyebrow"><span class="eyebrow-line"></span>FROM YOUR BOOKSHELF</span><div class="detail-card__header"><span class="status-tag ${finished ? 'status-tag--finished' : ''}"><span class="status-tag__dot"></span>${finished ? 'Finished' : 'Currently reading'}</span><h1>${escapeHtml(book.title)}</h1><p class="detail-author">by <strong>${escapeHtml(book.author)}</strong></p></div>
    <div class="detail-notes"><div class="detail-notes__heading"><span class="detail-notes__icon">✳</span><h2>Your notes</h2></div>${book.notes ? `<p>${escapeHtml(book.notes)}</p>` : '<p class="detail-notes__empty">No notes for this book yet. Sometimes the story says it all.</p>'}</div>
    <div class="detail-meta"><span>${finished ? 'FINISHED' : 'ADDED TO YOUR SHELF'}</span><span>${escapeHtml(formatDate(finished ? book.finishedAt : book.createdAt))}</span></div>
    <div class="detail-actions">${finished ? '' : `<form action="/books/${book.id}/finish?return=detail" method="post"><button class="primary-button" type="submit">Mark as finished <span aria-hidden="true">✓</span></button></form>`}<button class="share-button" type="button" data-copy-link><svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M8 10.8a3.5 3.5 0 0 0 5.2.4l2-2a3.5 3.5 0 0 0-5-5l-1.1 1.1M12 9.2a3.5 3.5 0 0 0-5.2-.4l-2 2a3.5 3.5 0 0 0 5 5l1.1-1.1" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg><span>Copy book link</span></button></div>
    <p class="detail-share-hint">Share this page with anyone — no account needed.</p>
    </div></article>
  </main>`, { title: book.title, page: 'detail' });
}

export function renderNotFound() {
  return layout(`<main class="not-found"><span class="eyebrow"><span class="eyebrow-line"></span>PAGE NOT FOUND</span><div class="not-found__number">404</div><h1>This chapter is missing.</h1><p>We couldn’t find the book you’re looking for.</p><a href="/" class="primary-button">Back to your shelf <span>${arrow}</span></a></main>`, { title: 'Not found', page: 'not-found' });
}

