import http from 'node:http';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { BookStore } from './book-store.js';
import { renderDetail, renderHome, renderNotFound } from './views.js';

const root = path.dirname(fileURLToPath(import.meta.url));
const assets = new Map([
  ['/styles.css', ['public/styles.css', 'text/css; charset=utf-8']],
  ['/app.js', ['public/app.js', 'text/javascript; charset=utf-8']],
  ['/favicon.svg', ['public/favicon.svg', 'image/svg+xml']],
]);

function send(response, status, body, type = 'text/html; charset=utf-8') {
  response.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
  response.end(body);
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

async function formData(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (body.length > 16_384) {
      const error = new Error('The submitted book is too long.');
      error.status = 413;
      throw error;
    }
  }
  return Object.fromEntries(new URLSearchParams(body));
}

function validateBook(form) {
  const title = String(form.title ?? '').trim();
  const author = String(form.author ?? '').trim();
  const notes = String(form.notes ?? '').trim();
  if (!title || !author) return { error: 'Please add both a book title and an author.' };
  if (title.length > 160 || author.length > 160 || notes.length > 4000) return { error: 'One of your entries is too long. Please shorten it and try again.' };
  return { title, author, notes };
}

export function createApp({ filePath = process.env.BOOKS_FILE || path.join(root, 'data/books.json') } = {}) {
  const store = new BookStore(filePath);

  return http.createServer(async (request, response) => {
    try {
      const url = new URL(request.url, 'http://localhost');
      const pathname = url.pathname;

      if (request.method === 'GET' && assets.has(pathname)) {
        const [filename, type] = assets.get(pathname);
        return send(response, 200, await readFile(path.join(root, filename)), type);
      }

      if (request.method === 'GET' && pathname === '/') {
        return send(response, 200, renderHome(await store.all()));
      }

      if (request.method === 'POST' && pathname === '/books') {
        const form = await formData(request);
        const book = validateBook(form);
        if (book.error) return send(response, 400, renderHome(await store.all(), { error: book.error, form }));
        await store.add(book);
        return redirect(response, '/');
      }

      const detail = pathname.match(/^\/books\/([0-9a-f-]{36})$/i);
      if (request.method === 'GET' && detail) {
        const book = (await store.all()).find((item) => item.id === detail[1]);
        return book ? send(response, 200, renderDetail(book)) : send(response, 404, renderNotFound());
      }

      const finish = pathname.match(/^\/books\/([0-9a-f-]{36})\/finish$/i);
      if (request.method === 'POST' && finish) {
        const book = await store.finish(finish[1]);
        if (!book) return send(response, 404, renderNotFound());
        return redirect(response, url.searchParams.get('return') === 'detail' ? `/books/${book.id}` : '/');
      }

      return send(response, 404, renderNotFound());
    } catch (error) {
      if (error.status === 413) return send(response, 413, 'The submitted book is too long.', 'text/plain; charset=utf-8');
      console.error('Request failed:', error);
      if (!response.headersSent) send(response, 500, 'Something went wrong loading your books.', 'text/plain; charset=utf-8');
      else response.end();
    }
  });
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT) || 3000;
  createApp().listen(port, () => console.log(`The Reading Room is ready at http://localhost:${port}`));
}

