args.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&display=swap');

:root{--paper:#f7f6f1;--white:#fffefa;--ink:#203631;--ink-soft:#41564d;--muted:#78837b;--line:#e7e7df;--accent:#ba694e;--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',Arial,sans-serif}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:14px;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
button,input,textarea{font:inherit}
button{cursor:pointer}
button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
svg{display:block;width:20px;height:20px}
.site-shell{max-width:1440px;margin:0 auto;padding:0 6.1%}
.site-header{height:100px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #dedfd6}
.brand{display:inline-flex;align-items:center;gap:11px;font-family:var(--serif);font-weight:600;font-size:22px;letter-spacing:-1.15px;white-space:nowrap}
.brand-mark{display:grid;place-items:center;width:35px;height:35px;background:var(--ink);color:#fff;border-radius:50%}
.brand-mark svg{width:20px;height:20px}
.brand-dot{color:var(--accent)}
.header-caption{display:flex;align-items:center;gap:15px;color:#889189;text-transform:uppercase;font-size:10px;font-weight:700;letter-spacing:2px}
.header-caption__line{width:24px;height:1px;background:#aeb7a9}
.hero{display:flex;align-items:center;justify-content:space-between;gap:55px;padding:76px 0 73px}
.hero__copy{max-width:725px}
.eyebrow{display:inline-flex;align-items:center;gap:11px;color:var(--accent);font-weight:700;font-size:10px;letter-spacing:2.25px;line-height:1.5}
.eyebrow-line{display:inline-block;width:22px;height:1px;background:currentColor}
.hero h1{font-family:var(--serif);font-weight:400;font-size:clamp(45px,4.55vw,68px);line-height:1.18;letter-spacing:-2.5px;margin:23px 0 20px}
.hero h1 em{color:var(--accent);font-weight:400}
.hero__copy>p{max-width:490px;color:#727d74;font-size:15px;line-height:1.8;margin:0}
.hero__summary{position:relative;overflow:hidden;flex:0 0 310px;min-height:211px;padding:28px 29px;background:#213c34;color:#f4f5e9;border-radius:4px;box-shadow:10px 10px 0 #e9e9de}
.hero__summary:after{content:'✳';position:absolute;right:-19px;top:-35px;color:rgba(240,238,217,.055);font-size:190px;line-height:1;pointer-events:none}
.summary-label{display:block;position:relative;z-index:1;font-size:10px;font-weight:700;letter-spacing:1.75px;color:#a8b8a8}
.summary-stats{display:flex;align-items:center;gap:29px;margin-top:24px;position:relative;z-index:1}
.summary-stats>div{display:flex;flex-direction:column;gap:3px;min-width:77px}
.summary-stats strong{font-family:var(--serif);font-weight:400;font-size:42px;line-height:1}
.summary-stats div span{font-size:11px;color:#c2cfc0}
.summary-divider{height:51px;width:1px;background:#50665b}
.summary-bottom{display:flex;justify-content:space-between;position:relative;z-index:1;border-top:1px solid #52685d;margin-top:24px;padding-top:14px;font-size:9px;letter-spacing:1.5px;color:#a8b8a8}
.summary-bottom span{font-size:16px;line-height:10px;color:#d4dfca}
.dashboard{display:grid;grid-template-columns:minmax(0,1fr) 335px;gap:45px;align-items:start;padding-bottom:95px}
.dashboard__shelves{min-width:0}
.shelf+.shelf{margin-top:67px}
.section-heading{padding-bottom:25px;border-bottom:1px solid #dcded4;margin-bottom:21px}
.section-heading h2{display:flex;align-items:baseline;gap:15px;font-family:var(--serif);font-size:31px;font-weight:500;letter-spacing:-.8px;margin:10px 0 6px}
.section-count{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:0;color:var(--accent);vertical-align:middle}
.section-heading p{margin:0;color:#879087;font-size:13px}
.book-list{display:grid;gap:13px}
.book-card{display:flex;gap:22px;min-height:186px;padding:17px;background:var(--white);border:1px solid #e9e9e1;border-radius:5px;box-shadow:0 5px 20px rgba(40,58,44,.025);transition:box-shadow .2s,transform .2s}
.book-card:hover{box-shadow:0 10px 28px rgba(40,58,44,.085);transform:translateY(-2px)}
.book-card__cover-link{display:block;flex:0 0 109px;align-self:stretch;min-height:151px}
.book-cover{position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between;width:100%;height:100%;min-height:151px;padding:13px 12px 10px;color:#f9f7e9;background:#516c60;box-shadow:inset -5px 0 rgba(0,0,0,.1),3px 4px 6px rgba(31,47,37,.12)}
.book-cover:before{content:'';position:absolute;width:130px;height:130px;left:33px;top:-65px;border:1px solid rgba(255,255,255,.3);border-radius:50%;box-shadow:0 0 0 24px rgba(255,255,255,.055),0 0 0 48px rgba(255,255,255,.04)}
.book-cover__ornament{position:relative;font-size:15px;line-height:1;opacity:.9}
.book-cover__type{position:relative;display:flex;flex-direction:column;gap:10px}
.book-cover__title{font-family:var(--serif);font-size:13px;font-weight:500;line-height:1.23;overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow-wrap:anywhere}
.book-cover__author{text-transform:uppercase;letter-spacing:1px;font-size:7px;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.book-cover__rule{height:1px;width:100%;background:rgba(255,255,255,.5);position:relative;margin-top:5px}
.cover-sage{background:#577366}.cover-clay{background:#b27158}.cover-ink{background:#3d5969}.cover-lavender{background:#85798d}.cover-ochre{background:#ac8952}
.book-card__body{min-width:0;flex:1;display:flex;flex-direction:column;justify-content:space-between;padding:2px 2px 1px 0}
.status-tag{display:inline-flex;align-items:center;gap:7px;color:#5c7963;background:#edf3eb;border-radius:50px;padding:6px 10px;font-size:10px;font-weight:700;letter-spacing:.15px}
.status-tag__dot{width:6px;height:6px;border-radius:50%;background:#7a9e74}
.status-tag--finished{color:#a66e55;background:#f8eee7}.status-tag--finished .status-tag__dot{background:#c18a65}
.book-card__info{margin:8px 0 12px}
.book-card h3{font-family:var(--serif);font-size:22px;font-weight:500;letter-spacing:-.45px;line-height:1.3;margin:0 0 3px;overflow-wrap:anywhere}
.book-card h3 a:hover,.text-link:hover,.back-link:hover{color:var(--accent)}
.book-author{color:#778178;margin:0;font-size:12px}
.book-card__excerpt{color:#8a9189;font-size:12px;line-height:1.5;margin:9px 0 0;white-space:pre-line;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}
.book-card__bottom{display:flex;justify-content:space-between;align-items:center;gap:10px;border-top:1px solid #eeeee7;padding-top:12px}
.book-card__bottom form{margin:0}
.text-link{display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:700;white-space:nowrap}
.text-link svg{width:16px;height:16px}
.finish-link{border:0;background:none;color:#8b9288;font-size:11px;padding:3px 0;text-align:right}
.finish-link:hover{color:var(--accent)}
.finish-link span{padding-left:3px}
