import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createApp } from '../server.js';

async function start(filePath) {
  const server = createApp({ filePath });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  return {
    base: `http://127.0.0.1:${server.address().port}`,
    close: () => new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve())),
  };
}

async function post(base, url, fields) {
  return fetch(`${base}${url}`, { method: 'POST', body: new URLSearchParams(fields), redirect: 'manual' });
}

test('books can be added, opened by link, finished, and recovered after a restart', async () => {
  const directory = await mkdtemp(path.join(os.tmpdir(), 'reading-room-'));
  const filePath = path.join(directory, 'books.json');
  let app = await start(filePath);
  try {
    const empty = await fetch(app.base);
    assert.equal(empty.status, 200);
    assert.match(await empty.text(), /Your next chapter starts here/);

    const added = await post(app.base, '/books', { title: 'The Left Hand of Darkness', author: 'Ursula K. Le Guin', notes: 'A favorite\nfor winter.' });
    assert.equal(added.status, 303);
    assert.equal(added.headers.get('location'), '/');

    const [book] = JSON.parse(await readFile(filePath, 'utf8'));
    assert.equal(book.title, 'The Left Hand of Darkness');
    assert.equal(book.status, 'reading');
    assert.equal(book.notes, 'A favorite\nfor winter.');
    assert.ok(book.id);

    const detail = await fetch(`${app.base}/books/${book.id}`);
    assert.equal(detail.status, 200);
    const detailHtml = await detail.text();
    assert.match(detailHtml, /The Left Hand of Darkness/);
    assert.match(detailHtml, /Ursula K\. Le Guin/);
    assert.match(detailHtml, /A favorite\nfor winter\./);
    assert.match(detailHtml, /Copy book link/);

    const finished = await post(app.base, `/books/${book.id}/finish?return=detail`, {});
    assert.equal(finished.status, 303);
    assert.equal(finished.headers.get('location'), `/books/${book.id}`);
    const saved = JSON.parse(await readFile(filePath, 'utf8'));
    assert.equal(saved[0].status, 'finished');
    assert.ok(saved[0].finishedAt);

    await app.close();
    app = await start(filePath);
    const home = await (await fetch(app.base)).text();
    assert.match(home, /Finished books/);
    assert.match(home, new RegExp(`/books/${book.id}`));
    assert.match(home, /The Left Hand of Darkness/);
    const reopened = await (await fetch(`${app.base}/books/${book.id}`)).text();
    assert.match(reopened, /Finished/);
    assert.doesNotMatch(reopened, /Mark as finished/);
  } finally {
    await app.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test('validation, escaping, not found pages, and concurrent writes', async () => {
  const directory = await mkdtemp(path.join(os.tmpdir(), 'reading-room-'));
  const filePath = path.join(directory, 'books.json');
  const app = await start(filePath);
  try {
    const invalid = await post(app.base, '/books', { title: '   ', author: 'Someone' });
    assert.equal(invalid.status, 400);
    assert.match(await invalid.text(), /Please add both a book title and an author/);

    const responses = await Promise.all(Array.from({ length: 8 }, (_, index) => post(app.base, '/books', {
      title: index === 0 ? '<script>alert(1)</script>' : `Book ${index}`,
      author: 'Writer',
      notes: 'Read soon',
    })));
    assert.ok(responses.every((response) => response.status === 303));
    const books = JSON.parse(await readFile(filePath, 'utf8'));
    assert.equal(books.length, 8);
    assert.equal(new Set(books.map((book) => book.id)).size, 8);

    const home = await (await fetch(app.base)).text();
    assert.match(home, /&lt;script&gt;alert\(1\)&lt;\/script&gt;/);
    assert.doesNotMatch(home, /<script>alert\(1\)<\/script>/);
    assert.equal((await fetch(`${app.base}/books/not-a-book`)).status, 404);
    assert.equal((await fetch(`${app.base}/styles.css`)).status, 200);
  } finally {
    await app.close();
    await rm(directory, { recursive: true, force: true });
  }
});

